function bloomSpeechKind(d,period){let qs=d.quests||[],done=qs.some(q=>q.done);if(d.closed)return 'evening';if((d.energy>0&&d.energy<=2)||(d.mood>0&&d.mood<=2))return 'support';if(done)return 'achievement';if(period==='morning')return 'morning';if(period==='evening'||period==='night')return 'evening';if(d.mood>0&&d.energy>0)return Math.floor(Date.parse(day())/86400000)%2===0?'mood':'random';return 'random'}
