let journalPromptKind='day',journalPromptIndex=0;
function journalPromptText(){return journalPromptBank[journalPromptKind][journalPromptIndex]}
function journalPromptChange(k){if(!Object.hasOwn(journalPromptBank,k))return;if(k===journalPromptKind)journalPromptIndex=(journalPromptIndex+1)%30;else{journalPromptKind=k;journalPromptIndex=0}let el=document.getElementById('journal-prompt-text');if(el)el.textContent=journalPromptText();document.querySelectorAll('[data-journal-prompt]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.journalPrompt===k)))}
