function journal(){let month=journalMonth||day().slice(0,7),dates=Object.keys(S.days).filter(k=>k.startsWith(month)),mem=S.mem.map((m,i)=>({m,i})).filter(({m})=>String(m.date).startsWith(month)),ds=dates.map(k=>S.days[k]),count=ds.reduce((n,d)=>n+d.quests.filter(q=>q.done).length,0),avg=k=>{let a=ds.map(d=>d[k]).filter(v=>v>0);return a.length?(a.reduce((n,v)=>n+v,0)/a.length).toFixed(1):'—'},first=new Date(month+'-01T12:00:00'),length=new Date(first.getFullYear(),first.getMonth()+1,0).getDate(),offset=(first.getDay()+6)%7;let calendar='<div class="journal-calendar">'+['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(x=>'<small>'+x+'</small>').join('')+'<span></span>'.repeat(offset)+Array.from({length},(_,i)=>{let k=month+'-'+String(i+1).padStart(2,'0'),d=S.days[k],has=mem.some(({m})=>String(m.date).slice(0,10)===k);return '<button type="button" class="journal-date '+(d?.closed?'chapter-day':d?.note||has||d?.mood?'memory-day':'')+(journalDate===k?' selected-day':'')+'" aria-pressed="'+(journalDate===k)+'" aria-label="'+k+'" onclick="journalDay(\''+k+'\')">'+(i+1)+(has?' ·':'')+'</button>'}).join('')+'</div>';let entries=mem.filter(({m})=>(!journalDate||String(m.date).slice(0,10)===journalDate)&&(journalFilter!=='favorites'||m.favorite)).map(({m,i})=>({date:m.date,html:'<div class="card memory '+(m.favorite?'memory-favorite':'')+'"><small>'+esc(m.date)+'</small><p class="memory-text">'+esc(m.text)+'</p>'+(m.photo?'<img loading="lazy" decoding="async" alt="Фотография воспоминания" src="'+esc(m.photo)+'">':'')+'<div class="row"><button aria-pressed="'+!!m.favorite+'" onclick="favoriteMemory('+i+')">'+(m.favorite?'♥ В избранном':'♡ В избранное')+'</button><button onclick="deleteMemory('+i+')">Удалить</button></div></div>'}));if(journalFilter!=='favorites'&&!journalDate)dates.forEach(k=>{let d=S.days[k];if(d.note||d.energy||d.mood||d.closed)entries.push({date:k,html:'<div class="card"><small>'+esc(k)+' · '+(d.closed?'Завершённая глава':'Запись дня')+'</small><p class="muted">Энергия: '+(d.energy||'—')+' · Настроение: '+(d.mood||'—')+'</p><p class="memory-text">'+esc(d.note||'')+'</p></div>'})});return '<div class="card"><h2>Месяц моей жизни</h2><input aria-label="Месяц дневника" type="month" value="'+month+'" onchange="journalSelect(this.value)">'+calendar+'<p class="journal-legend muted">• Воспоминание · Цветом отмечены записи дня</p><p>Глав завершено: '+ds.filter(d=>d.closed).length+' · Квестов: '+count+' · Моментов: '+mem.length+'</p><p class="muted">Средняя энергия: '+avg('energy')+' · Настроение: '+avg('mood')+'</p></div>'+journalDayView(journalDate)+'<div class="card journal-compose"><h2>Новый момент</h2><label>Дата воспоминания</label><input id="memoDate" type="date" max="'+day()+'" value="'+(journalDate&&journalDate<=day()?journalDate:day())+'">'+journalPromptPanel()+'<textarea aria-label="Текст воспоминания" id="memo" placeholder="Что произошло?"></textarea><p><input aria-label="Фото воспоминания" type="file" id="photo" accept="image/*"></p><button class="primary" onclick="memory()">Сохранить момент</button></div><h2>Мои воспоминания</h2><div class="row"><button class="'+(journalFilter==='all'?'active':'')+'" onclick="journalMode(\'all\')">Все записи</button><button class="'+(journalFilter==='favorites'?'active':'')+'" onclick="journalMode(\'favorites\')">♥ Избранное</button></div>'+ (entries.sort((a,b)=>String(b.date).localeCompare(String(a.date))).map(x=>x.html).join('')||'<div class="card journal-empty"><span aria-hidden="true">✧</span><h2>Здесь пока тихо</h2><p>Когда захочется сохранить момент, для него найдётся место.</p></div>')}async function photoBitmap(f){if(typeof createImageBitmap==='function'){try{return await createImageBitmap(f)}catch{}}return await new Promise((resolve,reject)=>{let u=URL.createObjectURL(f),img=new Image();img.onload=()=>{URL.revokeObjectURL(u);resolve(img)};img.onerror=()=>{URL.revokeObjectURL(u);reject(Error('photo'))};img.src=u})}let memorySaving=false;async function memory(){if(memorySaving)return;const field=$('memo'),input=$('photo'),t=field.value.trim(),f=input.files[0],date=$('memoDate').value;if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||date>day()){alert('Выбери дату не позднее сегодняшней.');return}if(!t&&!f){alert('Добавь текст или фотографию.');return}memorySaving=true;const button=field.parentElement.querySelector('button.primary');if(button){button.disabled=true;button.textContent='Сохраняем…'}try{let photo='';if(f){try{let img=await photoBitmap(f),c=document.createElement('canvas'),scale=Math.min(1,640/Math.max(img.width,img.height));c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);photo=c.toDataURL('image/jpeg',.55);if(img.close)img.close();if(!photo.startsWith('data:image/'))throw Error('photo')}catch{alert('Не удалось обработать фото. Выбери JPEG или PNG. Текст не удалён.');return}}const entry={date,text:t,photo};S.mem.push(entry);if(!save()){S.mem.splice(S.mem.indexOf(entry),1);return}journalMonth=date.slice(0,7);journalDate=date;journalFilter='all';if(tab==='journal'){render();bloomToast('✓ Момент сохранён в твоей книге жизни')}}finally{memorySaving=false;if(button){button.disabled=false;button.textContent='Сохранить момент'}}}function recurringPool(d){return []}
