const academyCards=[["science","Почему часы GPS требуют поправок?","quiz",["Из-за давления","Из-за гравитации и скорости","Из-за солнечного света"],1,"Общая и специальная теория относительности предсказывают разные темпы хода часов на орбите и Земле."],["science","На какой планете звёздные сутки длиннее года?","quiz",["Меркурий","Марс","Венера"],2,"Венера вращается вокруг оси за 243 земных суток, а вокруг Солнца — за 225."],["science","Почему кровь осьминога голубая?","quiz",["Медь в дыхательном белке","Высокая концентрация кислорода","Особенности питания"],0,"Гемоцианин содержит медь и переносит кислород."],["history","Где возникла клинопись?","quiz",["Месопотамия","Скандинавия","Австралия"],0,"Ранние образцы клинописи появились в Южной Месопотамии."],["history","Зачем строили римские акведуки?","fact","Они доставляли воду в города преимущественно благодаря силе тяжести."],["history","Что появилось раньше?","quiz",["Печатный станок Гутенберга","Первый полёт самолёта"],0,"Европейский печатный станок Гутенберга относится к XV веку, полёт братьев Райт — к 1903 году."],["culture","Что такое оригами?","quiz",["Складывание бумаги","Роспись ткани","Вышивка"],0,"Оригами — искусство складывания бумаги."],["culture","Почему в оркестре нужен дирижёр?","fact","Он помогает музыкантам согласовать темп, вступления, динамику и интерпретацию произведения."],["culture","Что такое фреска?","quiz",["Живопись по сырой штукатурке","Резьба по дереву","Мозаика из стекла"],0,"В классической технике фрески краска наносится на влажную штукатурку."],["facts","У какого животного три сердца?","quiz",["Осьминог","Дельфин","Пингвин"],0,"Два сердца осьминога направляют кровь к жабрам, третье — к остальному телу."],["facts","Почему лёд плавает?","fact","При замерзании вода образует структуру меньшей плотности, чем жидкая вода."],["facts","Может ли свет Солнца добраться до Земли за секунду?","quiz",["Да","Нет"],1,"В среднем свет проходит это расстояние примерно за 8 минут 20 секунд."],["science","Какой эффект меняет высоту звука приближающегося автомобиля?","quiz",["Доплера","Холла","Комптона"],0,"Относительное движение меняет воспринимаемую частоту волн."],["science","Почему Антарктида считается пустыней?","quiz",["Отсутствие почвы","Малое количество осадков","Отсутствие населения"],1,"Пустыни характеризуются малым количеством осадков, а не высокой температурой."],["science","Как называется способность воспринимать магнитное поле Земли?","quiz",["Эхолокация","Биолюминесценция","Магниторецепция"],2,"У некоторых птиц одним из предполагаемых механизмов является участие криптохромов."],["science","При каком условии вода кипит при комнатной температуре?","quiz",["Низкое давление","Высокая концентрация кислорода","Повышенная плотность"],0,"Кипение начинается, когда давление насыщенного пара достигает внешнего давления."],["science","Какие организмы обеспечивают около половины глобального производства кислорода?","quiz",["Наземные мхи","Фотосинтезирующие организмы океана","Хвойные деревья"],1,"Океанический фотосинтез даёт примерно половину глобального производства кислорода; значительная часть расходуется морскими экосистемами."],["history","Для чего предназначался Розеттский камень?","fact","На камне записан указ 196 года до нашей эры тремя видами письма. Сопоставление текстов помогло исследователям расшифровать египетские иероглифы."],["history","Где проходили древние Олимпийские игры?","quiz",["В Олимпии","В Риме","В Александрии"],0,"Игры проводились в святилище Олимпии в Древней Греции, традиционно их отсчитывают с 776 года до нашей эры."],["history","Что связывал Великий шёлковый путь?","fact","Это была сеть торговых маршрутов через Евразию, по которым перемещались не только товары, но и технологии, религиозные идеи и художественные традиции."],["history","Кто совершил первый полёт человека в космос?","quiz",["Юрий Гагарин","Нил Армстронг","Алексей Леонов"],0,"12 апреля 1961 года Юрий Гагарин совершил орбитальный полёт на корабле Восток-1."],["history","Где возникла ранняя технология изготовления бумаги?","quiz",["В Китае","В Исландии","В Перу"],0,"Древние образцы бумаги найдены в Китае. Цай Лунь традиционно связан с усовершенствованием технологии в 105 году нашей эры."],["culture","Что такое триптих?","quiz",["Произведение из трёх частей","Картина без рамы","Рисунок углём"],0,"Триптих состоит из трёх связанных частей, часто объединённых общим сюжетом."],["culture","Как устроен театр теней?","fact","Фигуры располагают между источником света и полупрозрачным экраном. Зрители видят их силуэты. Такие театральные традиции существуют во многих странах Азии."],["culture","Что означает слово а капелла?","quiz",["Пение без инструментального сопровождения","Очень громкое пение","Музыка только для фортепиано"],0,"А капелла называют вокальное исполнение без инструментального сопровождения."],["culture","Почему в витражах используют цветное стекло?","fact","Проходящий через стекло свет создаёт цветное изображение. В традиционных витражах отдельные фрагменты часто соединены свинцовыми профилями."],["facts","Как пчёлы сообщают о найденной пище?","fact","Медоносные пчёлы используют виляющий танец: направление и длительность его элементов передают сведения о направлении и расстоянии до источника пищи."],["facts","Какая планета вращается вокруг оси быстрее остальных?","quiz",["Юпитер","Земля","Марс"],0,"Сутки на Юпитере длятся примерно десять часов, хотя точная скорость вращения зависит от широты."],["facts","Почему у фламинго розовые перья?","quiz",["Из-за пигментов в пище","Из-за солёной воды","Из-за солнечного загара"],0,"Каротиноиды из пищи накапливаются в тканях и придают оперению розовые оттенки."],["facts","Как деревья сохраняют историю роста?","fact","У многих деревьев сезонные изменения роста образуют годичные кольца. Их ширина и особенности помогают изучать прошлые условия окружающей среды."],["science","Что происходит при квантовой запутанности двух частиц?","quiz",["Частицы обмениваются информацией быстрее скорости света","Результаты измерений демонстрируют особые квантовые корреляции","Частицы приобретают одинаковую массу и энергию"],1,"Квантовая запутанность связывает состояния частиц так, что результаты измерений демонстрируют необычные корреляции даже на огромном расстоянии. Использовать запутанность для передачи информации быстрее света невозможно."],["science","Благодаря какому явлению астрономы могут наблюдать далёкие галактики, свет которых иначе был бы слишком слабым?","quiz",["Гравитационное линзирование","Космологическое красное смещение","Интерференция световых волн"],0,"Массивные объекты искривляют пространство-время, изменяя траекторию света. Скопления галактик работают как природные линзы, увеличивая изображения более далёких объектов."],["science","Что изучает эпигенетика?","quiz",["Изменения последовательности ДНК при мутациях","Обмен генетическим материалом между организмами","Изменения активности генов без изменения последовательности ДНК"],2,"Химические метки и механизмы регуляции влияют на активность генов. На эти процессы могут воздействовать возраст, окружающая среда и образ жизни, при этом последовательность ДНК может оставаться неизменной."],["science","Как называется способность мозга перестраивать нейронные связи под влиянием опыта и обучения?","quiz",["Нейрогенез","Нейропластичность","Нейромодуляция"],1,"Мозг способен изменять структуру и силу связей между нейронами на протяжении жизни. Освоение языка, музыкального инструмента или профессионального навыка может менять работу нейронных сетей и во взрослом возрасте."],["science","Как тихоходки способны переживать экстремальное обезвоживание?","quiz",["Переходят в состояние криптобиоза","Заменяют воду в клетках кислородом","Ускоряют метаболизм"],0,"При криптобиозе обмен веществ снижается до крайне низкого уровня. Некоторые виды тихоходок способны переживать экстремальные температуры, радиацию и временное пребывание в космическом вакууме, а затем восстанавливать жизнедеятельность."],["science","Почему алмаз и графит обладают разными свойствами, хотя состоят из углерода?","quiz",["Разное количество протонов","Разные изотопы углерода","Разные структуры и химические связи"],2,"В алмазе атомы образуют прочную трёхмерную структуру, в графите — слои, которые легко скользят друг относительно друга. Такие формы одного элемента называются аллотропными модификациями."],["science","Как непосредственно измеряют современную скорость движения тектонических плит?","quiz",["Анализом атмосферного давления","Высокоточными спутниковыми измерениями координат","Измерением температуры океанических течений"],1,"Спутниковые навигационные системы фиксируют изменения положения земной поверхности. Плиты движутся со скоростью порядка нескольких сантиметров в год, сопоставимой со скоростью роста ногтей."],["science","Каков основной принцип действия мРНК-вакцин?","quiz",["Передача клеткам временной инструкции для создания антигена","Встраивание генетического материала возбудителя в ДНК человека","Введение готовых антител"],0,"Матричная РНК содержит инструкцию, по которой клетки временно производят антиген. Иммунная система формирует ответ, а мРНК естественным образом разрушается, не изменяя ДНК человека."],["science","Какое явление, помимо исчезновения электрического сопротивления, характерно для сверхпроводников?","quiz",["Эффект Зеемана","Эффект Холла","Эффект Мейснера"],2,"При переходе в сверхпроводящее состояние материал при определённых условиях вытесняет магнитное поле из своего объёма. Это эффект Мейснера. Сверхпроводники применяются в мощных магнитах, магнитной левитации и некоторых квантовых компьютерах."],["science","Почему биолюминесценция морских организмов чаще голубая или зеленоватая?","quiz",["Морская соль окрашивает свет","Свет этих длин волн хорошо распространяется в морской воде","При высоком давлении любой свет становится голубым"],1,"Биолюминесценция возникает благодаря химическим реакциям. В прозрачной океанической воде голубой и сине-зелёный свет распространяется особенно эффективно. Свечение служит для привлечения добычи, маскировки, защиты и коммуникации."],["science","Как называется симбиотическая связь грибов и корней растений?","quiz",["Микориза","Аллелопатия","Фототропизм"],0,"Грибные нити помогают растению получать воду и минеральные вещества, особенно фосфор. Взамен грибы могут получать органические соединения, образованные при фотосинтезе."],["science","За одной из трёх дверей автомобиль, за двумя другими козы. Ты выбираешь дверь. Ведущий знает ответ, всегда открывает другую дверь с козой и предлагает сменить выбор. Как выгоднее поступить?","quiz",["Оставить первоначальный выбор","Без разницы — вероятность 50%","Изменить первоначальный выбор"],2,"Парадокс Монти Холла: вероятность сразу выбрать автомобиль равна 1/3, а вероятность его нахождения за одной из остальных дверей — 2/3. При указанных правилах смена выбора даёт вероятность выигрыша 2/3."],["history","Для чего предназначался Антикитерский механизм?","quiz",["Расчёт стоимости товаров","Вычисление астрономических циклов","Определение глубины моря"],1,"Бронзовые зубчатые колёса позволяли рассчитывать астрономические циклы и предсказывать затмения."],["history","Какой римский император был философом-стоиком?","quiz",["Марк Аврелий","Октавиан Август","Адриан"],0,"Марк Аврелий оставил «Размышления» о самодисциплине и управлении собственными реакциями."],["history","Сколько приблизительно продолжалась Англо-занзибарская война 1896 года?","quiz",["Три дня","Шесть часов","Сорок минут"],2,"Конфликт продолжался менее часа и считается самой короткой документированной войной."],["history","Почему карантин связан с числом сорок?","quiz",["Группы по сорок пациентов","Изоляция судов на сорок дней","Сорок помещений больницы"],1,"Итальянское выражение quaranta giorni означает сорок дней. Так долго могли изолировать прибывающие суда."],["history","Как инки вели числовой учёт?","quiz",["Узелковые шнуры","Глиняные таблички","Металлические пластины"],0,"Кипу — система разноцветных шнуров и узлов для учёта населения и ресурсов."],["history","Что вызвало необычное похолодание в 1816 году?","quiz",["Минимум солнечной активности","Изменение Гольфстрима","Извержение Тамборы"],2,"Аэрозоли после извержения Тамборы в 1815 году уменьшили количество солнечного света у поверхности Земли."],["history","Для какой машины Ада Лавлейс описала алгоритм?","quiz",["Арифмометр Лейбница","Аналитическая машина Бэббиджа","Табулятор Холлерита"],1,"В 1843 году Лавлейс опубликовала алгоритм вычисления чисел Бернулли и предположила, что машины смогут работать не только с числами."],["history","Где появились первые широко используемые государственные бумажные деньги?","quiz",["Китай","Италия","Персия"],0,"При династии Сун бумажные деньги стали удобной альтернативой тяжёлым металлическим монетам."],["history","Почему после 4 октября 1582 года в некоторых странах наступило 15 октября?","quiz",["Ошибка переписчика","Изменение земного года","Переход на григорианский календарь"],2,"Десять дней пропустили для исправления накопленного расхождения юлианского календаря с астрономическим годом."],["history","Кто создал знаменитую библиотеку в Ниневии?","quiz",["Хаммурапи","Ашшурбанипал","Навуходоносор II"],1,"Ассирийский царь собрал клинописные таблички, среди которых обнаружили «Эпос о Гильгамеше»."],["history","Какой правитель XIV века прославился щедрой раздачей золота во время паломничества?","quiz",["Манса Муса","Саладин","Тамерлан"],0,"Правитель Мали совершил паломничество в Мекку в 1324 году. Источники связывают его расходы с изменением стоимости золота в Каире."],["history","Какой компонент помогал римскому бетону сохранять прочность в морской воде?","quiz",["Измельчённый мрамор","Древесная смола","Вулканический пепел"],2,"Вулканические материалы реагировали с известью и водой, образуя минералы, способствующие долговечности сооружений."],["history","Что ускорило появление единых стандартов времени в XIX веке?","quiz",["Развитие банков","Распространение железных дорог","Появление механических часов"],1,"Различия местного солнечного времени мешали составлению железнодорожных расписаний. Стандартизация помогла согласовать транспорт."],["history","Где металлический подвижный шрифт использовали до Гутенберга?","quiz",["Корея","Египет","Византия"],0,"Корейский буддийский текст «Чикчи» 1377 года — древнейшая сохранившаяся книга, напечатанная металлическим подвижным шрифтом."],["history","Почему английские кофейни XVII века называли университетами за пенни?","quiz",["Дешёвые учебники","Официальные экзамены","Доступные интеллектуальные дискуссии"],2,"За стоимость чашки кофе посетители могли знакомиться с новостями и обсуждать идеи с учёными, писателями и предпринимателями."],["history","Что ускорило международную стандартизацию паспортов?","quiz",["Первые авиакомпании","Первая мировая война и последующие конференции","Трансатлантический телеграф"],1,"В 1920 году конференция под эгидой Лиги Наций предложила стандарты паспортов, повлиявшие на современный формат."],["history","Как Эратосфен вычислил окружность Земли?","quiz",["Сравнил углы солнечных лучей в двух городах","Измерил длительность лунного затмения","Рассчитал скорость морских течений"],0,"Сравнив положение Солнца в Александрии и Сиене и используя расстояние между ними, Эратосфен оценил размеры Земли."],["history","Для чего символ @ использовали до электронной почты?","quiz",["Географические координаты","Обозначение дворянского рода","Торговые и бухгалтерские записи"],2,"Символ обозначал, в частности, цену за единицу товара. В 1971 году Рэй Томлинсон выбрал его для адресов электронной почты."],["history","Как назывались искусственные сельскохозяйственные участки ацтеков среди озёр?","quiz",["Террасы","Чинампы","Канаты"],1,"Чинампы создавали на мелководье и окружали каналами. Они позволяли получать высокие урожаи."],["history","Какое заведение стало основой страхового рынка Lloyd’s of London?","quiz",["Лондонская кофейня","Королевский монетный двор","Морская академия"],0,"Кофейня Эдварда Ллойда в конце XVII века стала местом встреч торговцев, судовладельцев и страховщиков морских рисков."],["culture","Как называется японское искусство восстановления керамики с подчёркиванием трещин золотом?","quiz",["Суми-э","Кинцуги","Икебана"],1,"В кинцуги повреждения становятся частью истории предмета. Традиционно используют лак уруси и металлический порошок."],["culture","Какую технику Леонардо да Винчи использовал для мягких переходов света и тени на лице Моны Лизы?","quiz",["Сфумато","Импасто","Пуантилизм"],0,"Сфумато создаёт плавные переходы оттенков без чётких границ. Выражение лица кажется изменчивым в зависимости от направления взгляда."],["culture","В чём особенность произведения Джона Кейджа «4′33″»?","quiz",["Исполняется только на ударных","Темп определяется сердцебиением","Исполнитель намеренно не извлекает звуков из инструмента"],2,"Окружающие звуки становятся частью произведения, делая каждое исполнение уникальным."],["culture","Какой элемент готической архитектуры позволил создавать высокие стены с огромными витражами?","quiz",["Кессонные потолки","Аркбутаны","Дорические колонны"],1,"Аркбутаны передают часть нагрузки от сводов на внешние опоры, позволяя увеличивать оконные проёмы."],["culture","Из какого минерала получали натуральный ультрамарин?","quiz",["Лазурит","Малахит","Аметист"],0,"Пигмент из лазурита был чрезвычайно дорогим из-за обработки и доставки сырья. Его часто использовали для одежд Девы Марии."],["culture","Как называется индонезийский театр плоских кожаных кукол?","quiz",["Кабуки","Катхакали","Ваянг-кулит"],2,"Кукловод управляет фигурками за освещённым экраном. Представления могут длиться всю ночь под музыку гамелана."],["culture","Что демонстрирует эффект Кулешова?","quiz",["Влияние освещения на восприятие возраста","Зависимость восприятия кадра от соседних кадров","Влияние скорости съёмки на пространство"],1,"Один и тот же нейтральный кадр воспринимается по-разному в зависимости от соседних кадров. Монтаж создаёт новые смыслы и эмоции."],["culture","Что означает японское эстетическое понятие «ма»?","quiz",["Значимое пространство или пауза","Симметричное расположение предметов","Только природные материалы"],0,"Ма подчёркивает ценность промежутков, тишины и незаполненного пространства в архитектуре, музыке и дизайне."],["culture","Какое объяснение уникального звучания скрипок Страдивари окончательно доказано?","quiz",["Особый состав лака","Древесина холодного климата","Единственная доказанная причина не установлена"],2,"Исследуют древесину, лак и конструкцию, но единого объяснения нет. В некоторых слепых тестах музыканты предпочитали современные скрипки."],["culture","Почему пуантилисты наносили краску отдельными точками?","quiz",["Для ускорения высыхания","Для оптического смешения цветов","Для облегчения реставрации"],1,"На расстоянии цветные точки визуально объединяются. Жорж Сёра и Поль Синьяк экспериментировали с восприятием цвета и света."],["culture","Как называется роман, построенный на переписке, дневниках и документах персонажей?","quiz",["Эпистолярный","Плутовской","Роман воспитания"],0,"Эпистолярная форма раскрывает события через субъективное восприятие героев. Примеры — «Опасные связи» и «Дракула»."],["culture","Как называется приём создания иллюзии трёхмерного пространства на плоскости?","quiz",["Кьяроскуро","Гризайль","Тромплёй"],2,"Trompe-l’œil означает «обман зрения». Перспектива, свет и тень создают иллюзию реальных окон, дверей и объёмных предметов."],["culture","Почему последовательность нот B–A–C–H имеет особое значение?","quiz",["Обозначает четыре темпа","Образует фамилию Баха","Используется для настройки оркестра"],1,"В немецкой нотации B — си-бемоль, H — си. Фамилия Баха превращается в музыкальный мотив из четырёх нот."],["culture","Какая школа стремилась объединить искусство, ремесло, архитектуру и промышленное производство?","quiz",["Баухаус","Рококо","Фовизм"],0,"Баухаус основан в Германии в 1919 году. Его представители соединяли функциональность, эстетику и массовое производство."],["culture","Как называются символические жесты рук в индийском классическом танце?","quiz",["Раги","Мантры","Мудры"],2,"Мудры передают эмоции, действия и образы. Вместе с мимикой и движениями они образуют язык повествования."],["culture","Что может обнаружить рентгенография старинной картины?","quiz",["Точные мысли художника","Скрытые изображения и изменения композиции","Точную дату каждого мазка"],1,"Рентгенография исследует внутренние слои живописи. Под известной картиной иногда находят другую композицию."],["culture","Что означает название направления «укиё-э»?","quiz",["Картины плывущего мира","Искусство вечных гор","Изображения небесных духов"],0,"Укиё-э изображало повседневность, природу и городские развлечения. Японские гравюры повлияли на Ван Гога и Моне."],["culture","Как называется создание и запись бытовых звуков специально для кино?","quiz",["Ротоскопирование","Колоризация","Фоли"],2,"Фоли-артисты воспроизводят шаги, шорох одежды и скрип дверей, иногда используя неожиданные материалы ради убедительного звучания."],["culture","Как называется орнамент из переплетающихся растительных и геометрических элементов в исламском искусстве?","quiz",["Меандр","Арабеска","Картуш"],1,"Арабески строятся на ритме и повторении форм, создавая ощущение бесконечности в архитектуре и декоративном искусстве."],["culture","Как называется наследие, включающее живые традиции, знания и навыки?","quiz",["Нематериальное культурное наследие","Археологическое наследие","Монументальное искусство"],0,"Оно включает ремёсла, устные предания, музыку, танцы и праздники. Его сохранение зависит от передачи опыта между поколениями."],["facts","Как называется запах дождя на сухой земле?","quiz",["Озонизация","Петрикор","Фитонцид"],1,"Один из компонентов запаха — геосмин, выделяемый почвенными микроорганизмами. Капли дождя поднимают мельчайшие частицы в воздух."],["facts","Способно ли человеческое тело излучать видимый свет?","quiz",["Да, но слишком слабый для зрения","Только при повышенной температуре","Нет, только отражает свет"],0,"Биохимические процессы сопровождаются сверхслабым световым излучением, которое регистрируют специальные приборы."],["facts","Какое животное производит экскременты кубической формы?","quiz",["Коала","Тасманийский дьявол","Вомбат"],2,"Кубическая форма возникает благодаря неодинаковой эластичности участков кишечника. Такие экскременты меньше скатываются."],["facts","Какой оттенок имеет большинство обычных стеклянных зеркал?","quiz",["Голубой","Зеленоватый","Фиолетовый"],1,"Обычные зеркала немного лучше отражают зелёную часть спектра. Это особенно заметно при многократных отражениях."],["facts","Какой плод с ботанической точки зрения является ягодой?","quiz",["Банан","Клубника","Малина"],0,"Банан соответствует ботаническому определению ягоды, клубника относится к многоорешкам, малина — к многокостянкам."],["facts","Как пчёлы сообщают направление и расстояние до пищи?","quiz",["Частотой жужжания","Прикосновениями усиков","Особым танцем"],2,"Виляющий танец передаёт направление относительно Солнца и приблизительное расстояние до пищи."],["facts","Какой организм без нервной системы известен экспериментами с привыканием к раздражителям и поиском маршрутов?","quiz",["Дрожжи","Слизевик Physarum","Морская губка"],1,"Physarum polycephalum способен находить эффективные маршруты к пище и демонстрировать привыкание, не имея мозга и нейронов."],["facts","Почему ледниковый лёд бывает насыщенно голубым?","quiz",["Сильнее поглощает красную часть спектра","Накапливает голубые минералы","Содержит больше кислорода"],0,"В плотном льду свет проходит большое расстояние, красные составляющие поглощаются сильнее, оставшийся свет выглядит голубым."],["facts","Какое морское животное использует камни для вскрытия раковин?","quiz",["Морской конёк","Морской лев","Калан"],2,"Каланы используют камни для вскрытия моллюсков и могут переносить их в складке кожи под передней лапой."],["facts","Почему некоторые песчаные дюны издают громкий низкий звук?","quiz",["Воздух в подземных пещерах","Согласованное движение песчинок","Магнитные свойства песка"],1,"Движение сухих песчинок по склону при определённых условиях создаёт коллективные колебания, напоминающие гул."],["facts","Почему некоторые цветы иначе выглядят в ультрафиолете?","quiz",["На лепестках есть невидимые человеку узоры","Лепестки мгновенно меняют пигментацию","Цветы выделяют светящиеся вещества"],0,"Ультрафиолетовые узоры видны многим насекомым и помогают опылителям находить нектар."],["facts","Какая птица специализируется на питании костями?","quiz",["Беркут","Андский кондор","Бородач"],2,"Бородач раскалывает крупные кости, сбрасывая их на камни. Кислая среда желудка помогает их переваривать."],["facts","Как называется полость в горной породе со стенками, покрытыми кристаллами?","quiz",["Конкреция","Жеода","Сталактит"],1,"Жеоды формируются при постепенном осаждении минералов из растворов внутри полости."],["facts","Почему собственный голос на записи звучит непривычно?","quiz",["При разговоре слышны также вибрации костей черепа","Микрофоны всегда повышают частоту","Мозг меняет высоту записи"],0,"При разговоре звук достигает внутреннего уха через воздух и ткани. Костная проводимость меняет воспринимаемый тембр."],["facts","Где обнаружили следы природных ядерных реакций возрастом около двух миллиардов лет?","quiz",["Исландия","Австралия","Габон"],2,"В месторождении Окло обнаружены следы естественных самоподдерживающихся реакций деления."],["facts","Из чего преимущественно состоят белые следы самолётов на большой высоте?","quiz",["Несгоревшее топливо","Кристаллы льда","Сконденсированный углекислый газ"],1,"Водяной пар смешивается с холодным воздухом и образует кристаллы льда. Длительность следа зависит от влажности атмосферы."],["facts","Могут ли растения самостоятельно повышать температуру цветков?","quiz",["Да, благодаря метаболическим процессам","Только накопленным солнечным теплом","Нет"],0,"Некоторые растения обладают термогенезом. Священный лотос способен поддерживать температуру цветка выше окружающей среды."],["facts","Какого цвета отдельные волоски белого медведя?","quiz",["Молочно-белые","Светло-серые","Практически бесцветные"],2,"Волоски лишены выраженной пигментации. Белый вид возникает благодаря рассеиванию света, а кожа имеет тёмную пигментацию."],["facts","Какой металл может расплавиться от тепла ладони?","quiz",["Олово","Галлий","Цинк"],1,"Температура плавления галлия около 29,8 °C. При достаточном нагревании он становится серебристой жидкостью."],["facts","Почему лунная радуга часто кажется белой?","quiz",["При слабом свете зрение хуже различает цвета","Лунный свет не содержит полного спектра","Ночные капли иначе преломляют свет"],0,"При слабом освещении преобладает зрение с участием палочек сетчатки. Камера с длительной выдержкой может запечатлеть цвета радуги."]],academyTopics={all:'Случайное открытие',science:'Наука',history:'История',culture:'Культура',facts:'Удивительные факты'},academyIcons={all:'✧',science:'⚗',history:'🏛',culture:'♫',facts:'◇'};let academyTopic='all',academyView='drum',academyId=-1,academyAnswer=-1,academyBusy=false;
