function selfDelete(i){let k=selfKey(i);if(!selfAnswer(i)||!confirm('Удалить этот ответ?'))return;let old=S.selfAnswers[k];delete S.selfAnswers[k];if(!save())S.selfAnswers[k]=old;atlasPageIndex=Math.max(0,Math.min(atlasPageIndex,atlasItems().length-1));render()}
